//! Vectors for SEND's sample claim, generated by `scripts/cpp_vectors/send_vectors.cpp`.

use std::collections::HashMap;

use fp_core::chain::rounds::SampleSeed;
use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::iop::relation::{Codes, OracleShape, Part, RowKind, Statement};
use fp_core::iop::send::sample_form;
use fp_core::iop::send_pad::send_pad;

const VECTORS: &str = include_str!("../../fixtures/send_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}

fn f(s: &str) -> F {
    F(u64::from_str_radix(s, 16).unwrap())
}

fn e(s: &str) -> E {
    let p: Vec<&str> = s.trim_start_matches('=').split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([f(p[0]), f(p[1]), f(p[2])])
}

fn eseq(s: &str) -> Vec<E> {
    s.trim_start_matches('=').split(';').map(e).collect()
}

#[test]
fn send_vectors_match_the_cpp_reference() {
    let mut lines = VECTORS.lines();
    let mut codes = Codes::default();
    codes.base.push(Code { log_n: 3, ell: 4, r: 2 });
    codes.mask.push(Code { log_n: 2, ell: 2, r: 1 });
    let mut s = Statement::new(codes.clone());
    let mut shape = OracleShape::default();
    shape.name = "send-shape".into();
    shape.code = 0;
    shape.main_rows = 2;
    shape.main_deg = 1;
    shape.mask_rows = 2;
    shape.mask_code = 0;
    shape.answers = 2;
    let o = s.sent(shape.clone());

    let line = lines.next().unwrap();
    assert_eq!(
        line,
        "CUBE has_main=1 has_mask=1 main_row_bits=1 main_bits=3 mask_row_bits=1 mask_bits=2 bits=4"
    );
    let line = lines.next().unwrap();
    let pads: Vec<String> = line["PAD".len()..].split_whitespace().map(str::to_string).collect();
    let got: Vec<String> = send_pad(&codes, &shape)
        .iter()
        .map(|p| format!("{}:{}:{}", p.part as u32, p.index, p.answer))
        .collect();
    assert_eq!(got, pads);

    let line = lines.next().unwrap();
    let kv = fields(line);
    let z = eseq(kv["z"]);
    let beta = e(kv["beta"]);
    assert_eq!(z.len(), 4);
    let seed = SampleSeed { z, beta };

    for answer in 0..2u32 {
        let line = lines.next().unwrap();
        let kv = fields(line);
        let row = sample_form(&s, o, &seed, answer);
        let name = line.split("name=").nth(1).unwrap().split(" kind=").next().unwrap();
        assert_eq!(row.name, name);
        assert_eq!(row.kind, RowKind::Sample);
        assert_eq!(row.target, e(kv["target"]));
        assert!(line.contains(&format!("answer={}", answer)));

        let line = lines.next().unwrap();
        let want: Vec<E> = line["MAIN".len()..].split_whitespace().map(e).collect();
        for (j, v) in want.iter().enumerate() {
            assert_eq!(row.coefficient(o, Part::Main, j as u64), *v, "main {} answer {}", j, answer);
        }
        let line = lines.next().unwrap();
        let want: Vec<E> = line["MASK".len()..].split_whitespace().map(e).collect();
        for (j, v) in want.iter().enumerate() {
            assert_eq!(row.coefficient(o, Part::Mask, j as u64), *v, "mask {} answer {}", j, answer);
        }
    }
    assert!(lines.next().is_none());
}
